//! Parity: the config registry resolves the same values as Python's `get_config` for the
//! synthetic roots under `fixtures/config_cases/` (generated by `fixtures/gen_config.py`), and
//! the embedded defaults match `meerschaum.config._default.default_config`.

mod common;

use std::path::Path;

use meerschaum_core::config::{Config, ConfigOptions, GetOptions, default_config, paths::posix};
use meerschaum_core::{Map, Value};

fn copy_dir(src: &Path, dst: &Path) {
    std::fs::create_dir_all(dst).unwrap();
    for entry in std::fs::read_dir(src).unwrap() {
        let entry = entry.unwrap();
        let target = dst.join(entry.file_name());
        if entry.file_type().unwrap().is_dir() {
            copy_dir(&entry.path(), &target);
        } else {
            std::fs::copy(entry.path(), target).unwrap();
        }
    }
}

/// Compare a whole-config snapshot (`get_config()` or `get_config('_symlinks')`).
///
/// Python's own imports and console helpers load other top-level keys into the global config
/// (`warn()` reads `formatting`, importing reads `system` and `api`), so the snapshots differ in
/// which keys are present and in their order. Every key the Rust registry loaded must match.
///
/// `formatting` is skipped: both sides load it raw while resolving `MRSM{formatting:...}` default
/// symlinks, but Python's `warn()` then calls `get_config('formatting', ...)`, which re-substitutes
/// it in place.
fn assert_snapshot(actual: &Value, expected: &Value, context: &str) {
    let (Some(a), Some(e)) = (actual.as_list(), expected.as_list()) else {
        panic!("snapshot is not a tuple for {context}");
    };
    assert_eq!(a[0], e[0], "validity for {context}");
    let (Some(am), Some(em)) = (a[1].as_map(), e[1].as_map()) else {
        common::assert_same(&a[1], &e[1], context);
        return;
    };
    for (k, v) in am {
        if k == "formatting" {
            continue;
        }
        let ev = em
            .get(k)
            .unwrap_or_else(|| panic!("Python snapshot lacks key '{k}' for {context}"));
        if k == "_symlinks" {
            for (sk, sv) in v.as_map().unwrap() {
                if sk == "formatting" {
                    continue;
                }
                common::assert_same(
                    sv,
                    ev.get(sk).unwrap_or(&Value::Null),
                    &format!("{context} _symlinks.{sk}"),
                );
            }
        } else {
            common::assert_same(v, ev, &format!("{context} key '{k}'"));
        }
    }
}

fn normalize(value: &Value, root: &str) -> Value {
    let text = value.to_json_string().replace(root, "{ROOT}");
    Value::from_json_str(&text).unwrap()
}

fn run_case(case_dir: &Path) {
    let name = case_dir.file_name().unwrap().to_string_lossy().to_string();
    let case = Value::from_json_str(&std::fs::read_to_string(case_dir.join("case.json")).unwrap())
        .unwrap();
    let expected =
        Value::from_json_str(&std::fs::read_to_string(case_dir.join("expected.json")).unwrap())
            .unwrap();
    let tmp = tempfile::tempdir().unwrap();
    let tmp_path = tmp.path().canonicalize().unwrap();
    let root = tmp_path.join("root");
    copy_dir(&case_dir.join("root"), &root);
    let plugins = tmp_path.join("plugins");
    std::fs::create_dir_all(&plugins).unwrap();
    let root_str = posix(&root);

    let mut env = vec![
        ("MRSM_ROOT_DIR".to_string(), root_str.clone()),
        ("MRSM_PLUGINS_DIR".to_string(), posix(&plugins)),
    ];
    for (k, v) in case.get("env").and_then(Value::as_map).unwrap() {
        env.push((k.clone(), v.as_str().unwrap().replace("{ROOT}", &root_str)));
    }
    let opts = ConfigOptions {
        env,
        home: tmp_path.clone(),
        windows: false,
        package_root: None,
        cpu_count: expected.get("cpu_count").and_then(Value::as_i64).unwrap(),
        allow_writes: true,
    };
    let config = Config::new(opts).unwrap();

    let queries = case.get("queries").and_then(Value::as_list).unwrap();
    let results = expected.get("results").and_then(Value::as_list).unwrap();
    for (i, (query, expected_result)) in queries.iter().zip(results).enumerate() {
        let keys: Vec<String> = query
            .get("keys")
            .and_then(Value::as_list)
            .unwrap()
            .iter()
            .map(|k| k.as_str().unwrap().to_string())
            .collect();
        let key_refs: Vec<&str> = keys.iter().map(String::as_str).collect();
        let mut get_opts = GetOptions::default();
        if let Some(Value::Map(o)) = query.get("opts") {
            let flag = |k: &str, d: bool| o.get(k).and_then(Value::as_bool).unwrap_or(d);
            get_opts = GetOptions {
                patch: flag("patch", true),
                substitute: flag("substitute", true),
                write_missing: flag("write_missing", true),
                warn: flag("warn", true),
            };
        }
        let (valid, value) = config.get_with(&key_refs, get_opts);
        let actual = Value::List(vec![Value::Bool(valid), value]);
        let context = format!("case '{name}' query #{i} {keys:?}");
        let actual = normalize(&actual, &root_str);
        if keys.is_empty() {
            assert_snapshot(&actual, expected_result, &context);
        } else if keys == ["_symlinks"] {
            let wrap = |v: &Value| {
                let l = v.as_list().unwrap();
                let mut m = Map::new();
                m.insert("_symlinks".into(), l[1].clone());
                Value::List(vec![l[0].clone(), Value::Map(m)])
            };
            assert_snapshot(&wrap(&actual), &wrap(expected_result), &context);
        } else {
            common::assert_same(&actual, expected_result, &context);
        }
    }

    // Every file in the config directory afterwards must exist on the Python side, with
    // identical contents for JSON files. Python may have more files: its own import-time lookups
    // (e.g. `system:experimental`) write default files that the registry alone does not.
    let config_dir = config.paths().config_dir;
    let expected_files = expected
        .get("config_files")
        .and_then(Value::as_map)
        .unwrap();
    for entry in std::fs::read_dir(&config_dir).unwrap() {
        let n = entry.unwrap().file_name().to_string_lossy().to_string();
        let expected_content = expected_files
            .get(&n)
            .unwrap_or_else(|| panic!("case '{name}': Python did not write '{n}'"));
        if n.ends_with(".json") {
            let content = std::fs::read_to_string(config_dir.join(&n)).unwrap();
            assert_eq!(
                content.replace(&root_str, "{ROOT}"),
                expected_content.as_str().unwrap(),
                "case '{name}' file {n}"
            );
        }
    }
    assert_eq!(
        root.join("patch_config").exists(),
        expected
            .get("patch_dir_exists")
            .and_then(Value::as_bool)
            .unwrap(),
        "case '{name}' patch dir"
    );
}

#[test]
fn config_cases_match_python() {
    let cases = common::fixtures().join("config_cases");
    let mut dirs: Vec<_> = std::fs::read_dir(&cases)
        .unwrap()
        .map(|e| e.unwrap().path())
        .filter(|p| p.is_dir())
        .collect();
    dirs.sort();
    assert!(!dirs.is_empty());
    for dir in dirs {
        run_case(&dir);
    }
}

#[test]
fn default_config_matches_python() {
    let fixture = common::load_fixture("default_config.json");
    let root = fixture.get("root").and_then(Value::as_str).unwrap();
    let cpu = fixture.get("cpu_count").and_then(Value::as_i64).unwrap();
    let windows = fixture.get("windows").and_then(Value::as_bool).unwrap();
    let actual = default_config(root, cpu, windows);
    common::assert_same(
        &Value::Map(actual),
        fixture.get("default_config").unwrap(),
        "default_config",
    );
}
